        v2 = labels[3*g + 2]
        edges.append(abs(v0 - v1))
        edges.append(abs(v1 - v2))
        edges.append(abs(v2 - v0))

    for g in range(4):
        for i in range(3):
            v_g_i = labels[3*g + i]
            v_g1_i = labels[3*(g+1) + i]
            edges.append(abs(v_g_i - v_g1_i))

    if len(set(edges)) != 27:
        return False
    if any(e < 1 or e > 27 for e in edges):
        return False
    return True

